const app = require('./app');
const request = require('supertest');
const express = require('express');

// Test the endpoint
async function test() {
  // Test 1: Rule that evaluates to true
  let res = await request(app).post('/check').send({
    rule: 'ctx.amount > 100',
    context: { amount: 150 }
  });
  console.log('Test 1 (amount > 100, amount=150):', res.body);

  // Test 2: Rule that evaluates to false
  res = await request(app).post('/check').send({
    rule: 'ctx.amount > 100',
    context: { amount: 50 }
  });
  console.log('Test 2 (amount > 100, amount=50):', res.body);

  // Test 3: Using req in expression
  res = await request(app).post('/check').send({
    rule: 'ctx.user.role === \"admin\" && req.body.context.amount > 50',
    context: { user: { role: 'admin' }, amount: 100 }
  });
  console.log('Test 3 (complex rule):', res.body);
}

test();
"

